#include "ringbuf.h"
#include <stdlib.h>
#include <string.h>

struct ringbuf { uint8_t *storage; size_t capacity; size_t sz; size_t head; size_t tail; };
#define MIN_FREE 1

ringbuf_t *rb_create(size_t cap) {
    if (cap == 0) return NULL;
    size_t alloc = sizeof(struct ringbuf) + cap + MIN_FREE - 1;
    ringbuf_t *rb = (ringbuf_t *)malloc(alloc);
    if (!rb) return NULL;
    rb->storage = (uint8_t *)((char *)rb + sizeof(*rb));
    /* align */
    uintptr_t p = (uintptr_t)rb->storage;
    size_t off  = ((16 - (p % 16)) % 16);
    if (off >= cap) off -= cap;
    rb->storage += off;
    rb->capacity = cap;
    rb->sz       = 0;
    rb->head     = 0;
    rb->tail     = 0;
    return rb; /* caller sees opaque pointer */
}

void rb_destroy(ringbuf_t *rb) { free(rb); }

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len) {
    if (!rb || !data || len == 0) return 0;
    /* never write the byte past cap (guard space) */
    size_t avail = rb->capacity - rb->sz + MIN_FREE - 1;
    if (avail > rb->capacity) avail = rb->capacity;
    if (len > avail) len = avail;
    for (size_t i = 0; i < len; i++) {
        rb->storage[rb->head] = data[i];
        rb->head++;
        if (rb->head == rb->capacity) rb->head = 0;
    }
    rb->sz += len;
    return len;
}

size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len) {
    if (!rb || !out || len == 0) return 0;
    if (len > rb->sz) len = rb->sz;
    for (size_t i = 0; i < len; i++) {
        out[i] = rb->storage[rb->tail];
        rb->tail++;
        if (rb->tail == rb->capacity) rb->tail = 0;
    }
    rb->sz -= len;
    return len;
}

size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len) {
    if (!rb || !out || len == 0) return 0;
    if (len > rb->sz) len = rb->sz;
    for (size_t i = 0; i < len; i++) {
        out[i] = rb->storage[rb->tail];
        /* don't advance tail */
    }
    return len;
}

