        rb->tail   = 0;
    }
}

#include "ringbuf.h"
#include <stdlib.h>
#include <string.h>

struct ringbuf {
    uint8_t *buf;
    size_t   capacity;
    size_t   stored;  /* bytes currently stored */
    size_t   head;    /* next write position */
    size_t   tail;    /* next read position */
};

ringbuf_t *rb_create(size_t capacity) {
    if (capacity == 0) return NULL;

    ringbuf_t *rb = (ringbuf_t *)calloc(1, sizeof(*rb));
    if (!rb) return NULL;

    rb->buf   = (uint8_t *)malloc(capacity);
    if (!rb->buf) { free(rb); return NULL; }
    rb->capacity = capacity;
    rb->stored   = 0;
    rb->head     = 0;
    rb->tail     = 0;
    return rb;
}

void rb_destroy(ringbuf_t *rb) {
    if (!rb) return;
    free(rb->buf);
    free(rb);
}

/* Internal helper: how many bytes can be written right now? */
static size_t write_avail(const struct ringbuf *rb) {
    /* capacity is exactly as given — never use guard space */
    return rb->capacity - rb->stored;
}

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len) {
    if (!rb || !data || len == 0) return 0;
    size_t n = write_avail(rb);
    if (len > n) len = n;
    for (size_t i = 0; i < len; i++) {
        size_t pos = rb->head + i;
        if (pos >= rb->capacity) pos -= rb->capacity;
        rb->buf[pos] = data[i];
    }
    rb->head += len;
    if (rb->head >= rb->capacity) rb->head -= rb->capacity;
    rb->stored += len;
    return len;
}

size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len) {
    if (!rb || !out || len == 0) return 0;
    if (len > rb->stored) len = rb->stored;
    for (size_t i = 0; i < len; i++) {
        size_t pos = rb->tail + i;
        if (pos >= rb->capacity) pos -= rb->capacity;
        out[i] = rb->buf[pos];
    }
    rb->tail += len;
    if (rb->tail >= rb->capacity) rb->tail -= rb->capacity;
    rb->stored -= len;
    return len;
}

size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len) {
    if (!rb || !out || len == 0) return 0;
    if (len > rb->stored) len = rb->stored;
    for (size_t i = 0; i < len; i++) {
        size_t pos = rb->tail + i;
        if (pos >= rb->capacity) pos -= rb->capacity;
        out[i] = rb->buf[pos];
    }
    return len;
}

size_t rb_size(const ringbuf_t *rb) { if (!rb) return 0; return rb->stored; }
size_t rb_capacity(const ringbuf_t *rb) { if (!rb) return 0; return rb->capacity; }

void rb_clear(ringbuf_t *rb) {
    if (!rb) return;
    rb->stored = 0;
    rb->head   = 0;
    rb->tail   = 0;
}

#include "ringbuf.h"
