int main(void) {
    /* Test 1: basic create/destroy/capacity */
    ringbuf_t *rb = rb_create(8);
    assert(rb != NULL);
    assert(rb_capacity(rb) == 8);
    assert(rb_size(rb) == 0);

    rb_destroy(rb);
    rb_destroy(NULL); /* should not crash */

