    rb = rb_create(4);
    assert(rb != NULL);

    /* Write all 4 slots */
    uint8_t src[] = {1, 2, 3, 4};
    size_t w = rb_write(rb, src, sizeof(src));
    assert(w == 4);
    assert(rb_size(rb) == 4);

