    uint8_t extra[] = {99};
    w = rb_write(rb, extra, sizeof(extra));
    assert(w == 0);
    assert(rb_size(rb) == 4);

    /* Read oldest */
    uint8_t dst[1];
    size_t r = rb_read(rb, dst, sizeof(dst));
    assert(r == 1 && dst[0] == 1);
    assert(rb_size(rb) == 3);

    /* Peek (doesn't remove) */
    uint8_t p;
    rb_peek(rb, &p, 1);
    assert(p == 2);
    assert(rb_size(rb) == 3); /* peek doesn't change size */

    /* Read remaining 3 */
    uint8_t dst2[4];
    r = rb_read(rb, dst2, sizeof(dst2));
    assert(r == 3);
    assert(dst2[0] == 2 && dst2[1] == 3 && dst2[2] == 4);
    assert(rb_size(rb) == 0);

    /* Test 3: write-read past wrap boundary */
    uint8_t a[]  = {10, 20};
    rb_write(rb, a, sizeof(a));   /* stored=2, head at position 2 */

    uint8_t b[] = {30, 40};
    rb_write(rb, b, sizeof(b));   /* stored=4, head wraps: pos (2+2) %4 = 0... wait no. */
