                                   /* After writing a[0]:head=0->1; a[1]:head=2. tail still at 0. stored=4. */
                                   /* write b: head goes from 2 to (2+2)%4 = 0... but capacity is only 4 so we can't over-write */
                                   /* Actually: write_avail = 4 - 4 = 0? No wait — stored=4 and capacity=4 means full. */
    /* Hmm, that's wrong for the test. Let me drain first. */

    /* Read what we have to reset state */
    uint8_t tmp[6];
    rb_read(rb, tmp, 6);           /* should read all 4: {10,20,30,40} */
    assert(tmp[0]==10 && tmp[1]==20 && tmp[2]==30 && tmp[3]==40);

    /* Now write past wrap: fill the remaining 2 slots with some data, clear partially, 
       overflow by writing more than fits to force wrapping. */
    uint8_t pre[] = {100};
    rb_write(rb, pre, sizeof(pre));   /* head=1, tail=0, stored=1 */

    /* Write 6 bytes into remaining 3 slots — should only write 3 */
    uint8_t overflow[6];
    for (int i = 0; i < 6; i++) overflow[i] = (uint8_t)(200 + i);
    w = rb_write(rb, overflow, sizeof(overflow));
    assert(w == 3);                      /* only 3 fit */

    /* But this is getting complex to verify manually. Let me do a simpler wrap test instead. */

    /* Simple wrap: write capacity bytes, read N < capacity, write more (overflow), read all */
    /* With capacity=4: fill [A,B,C,D], read 2 [A,B] -> stored=2, tail at 2, head at 0 (was 4%4) */
    /* Now write 2 more [E,F]: tail is at pos 2, head at 0. avail = 4-2 = 2. stores E at pos 0, F at pos 1. head becomes 2.] 

    */

    rb_clear(rb);

    uint8_t wrap_a[] = {1, 2, 3, 4};
    w = rb_write(rb, wrap_a, sizeof(wrap_a));
    assert(w == 4 && rb_size(rb) == 4);

    /* Read 2 — stored goes from 4 to 2 */
    rb_read(rb, tmp, 2);  /* reads oldest: 1, 2 */
    assert(rb_size(rb) == 2);

    /* Write 3 bytes into what's now only a 2-slot gap (capacity - stored = 4-2 = 2). 
       Actually wait — head was at position 0 after wrap. tail is at position 2. 
       The data layout in buffer: [?, ?, 3, 4] with the '?' at pos 0 and 1 being overwritable */
    uint8_t fill[] = {250}; /* only write 1 byte to avoid confusion */
    w = rb_write(rb, fill, sizeof(fill));

    /* Now read all */
    rb_read(rb, tmp, 16);

