int main(void) {
    ringbuf_t *rb;
    uint8_t buf[64];
    size_t r, w;

    /* --- create/destroy/capacity --- */
    rb = rb_create(8);
    assert(rb != NULL);
    assert(rb_capacity(rb) == 8);
    assert(rb_size(rb) == 0);
    rb_destroy(NULL); /* safe */

    /* --- write 4, fill all --- */
    for (unsigned i = 0; i < 8; i++) buf[i] = (uint8_t)(i + 1);
    w = rb_write(rb, buf, 4); /* writes only 4: {1,2,3,4} */
    assert(w == 4 && rb_size(rb) == 4);

    /* --- write more when full --- */
    r = rb_write(rb, buf + 4, 4);
    assert(r == 0 && rb_size(rb) == 4);

    /* --- peek (doesn't remove) --- */
    uint8_t p;
    rb_peek(rb, &p, 1);
    assert(p == 1 && rb_size(rb) == 4);
    rb_peek(NULL, &p, 1); /* safe: returns 0 */

    /* --- read 2 oldest --- */
    r = rb_read(rb, buf, 1);
    assert(r == 1 && buf[0] == 1 && rb_size(rb) == 3);
    r = rb_read(rb, buf + 1, 10);       /* reads remaining 3: {2,3,4} */
    assert(r == 3 && buf[1]==2 && buf[2]==3 && buf[3]==4 && rb_size(rb) == 0);

    /* --- read from empty is 0 --- */
    r = rb_read(rb, buf, 10);
    assert(r == 0);

    /* --- wrap-around test (capacity=4 ring) --- */
    rb = rb_create(4);       /* ring of size 4 */

    /* fill [A,B,C,D] where A=10..D=13, head wraps to pos[0], tail=0, stored=4 */
    w = rb_write(rb, (uint8_t[]){10,11,12,13}, 4);
    assert(w == 4 && rb_size(rb) == 4);

    /* drain [A,B] -> stored=2, tail=2, head=0(already was), avail=2 */
    r = rb_read(rb, buf, 2);
    assert(r == 2 && buf[0]==10 && buf[1]==11 && rb_size(rb) == 2);

    /* write [X] -> avail=2 so 1 fits. stores at pos[head]=pos[0], head->1 */
    w = rb_write(rb, (uint8_t[]){99}, 1);
    assert(w == 1 && rb_size(rb) == 3);           /* stored = 2+1 = 3 */

    /* read all: oldest first from tail=2 through wrap: {pos[2]=12, pos[3]=13, pos[0]=99} */
    r = rb_read(rb, buf, 64);                         /* min(read=64,min(stored,64)) = stored=3 */
    assert(r == 3 && buf[0] == 12/*oldest*/ && buf[1]==13&&buf[2]==99/*newest*/);
    assert(rb_size(rb) == 0);

    printf("All tests passed!\n");
    return 0;
}

#include "ringbuf.h"
#include <stdlib.h>
#include <string.h>

struct ringbuf {
    uint8_t *buf;
    size_t   capacity;
    size_t   stored;  /* bytes currently stored */
    size_t   head;    /* next write index (0 .. capacity-1) */
    size_t   tail;    /* next read index (0 .. capacity-1) */
};

ringbuf_t *rb_create(size_t capacity) {
    if (capacity == 0) return NULL;
    ringbuf_t *rb = (ringbuf_t *)calloc(1, sizeof(*rb));
    if (!rb) return NULL;
    rb->buf      = (uint8_t *)malloc(capacity);
    if (!rb->buf) { free(rb); return NULL; }
    rb->capacity = capacity;
    rb->stored   = 0;
    rb->head     = 0;
    rb->tail     = 0;
    return rb;
}

void rb_destroy(ringbuf_t *rb) {
    if (!rb) return;
    free(rb->buf);
    free(rb);
}

/* Internal: bytes that can be written without overwriting unread data.
 * We reserve 1 slot to distinguish full from empty: head == tail means empty,
 * (head + 1) % capacity == tail means full. */
static size_t write_avail(const struct ringbuf *rb) {
    size_t gap = rb->capacity - rb->stored;  /* always > 0 for valid rings */
    return gap < rb->capacity ? gap : 0;
}

/* Move pos toward head, wrapping at capacity. Advance by 'n' steps. Returns true if full after wrap. */
static void move_head(struct ringbuf *rb, size_t n) {
    /* For safety with large n, clamp to avoid overflow of (head + n) in normal use:
     * stored is always < capacity so head won't advance more than capacity-1 per write. */
    size_t old = rb->head;
    if (rb->capacity - old >= n) {
        rb->head = old + n;  /* no wrap */
    } else {
        rb->head = old + n - rb->capacity;  /* exactly one wrap, safe because n < capacity */
    }
}

static void move_tail(struct ringbuf *rb, size_t n) {
    size_t old = rb->tail;
    if (rb->capacity - old >= n) {
        rb->tail = old + n;
    } else {
        rb->tail = old + n - rb->capacity;
    }
}

/* Copy one byte at write position */
static void write_at(struct ringbuf *rb, uint8_t val) {
    rb->buf[rb->head] = val;
}

size_t rb_write(ringbuf_t *ringbuf, const uint8_t *data, size_t len) {
    struct ringbuf *rb = (struct ringbuf *)ringbuf;
    if (!rb || !data || len == 0) return 0;
    size_t n = write_avail(rb);
    if (len > n) len = n;
    for (size_t i = 0; i < len; i++) {
        write_at(rb, data[i]);
        move_head(rb, 1);
    }
    rb->stored += len;
    return len;
}

size_t rb_read(ringbuf_t *ringbuf, uint8_t *out, size_t len) {
    struct ringbuf *rb = (struct ringbuf *)ringbuf;
    if (!rb || !out || len == 0) return 0;
    if (len > rb->stored) len = rb->stored;
    for (size_t i = 0; i < len; i++) {
        out[i] = rb->buf[rb->tail];
        move_tail(rb, 1);
    }
    rb->stored -= len;
    return len;
}

size_t rb_peek(const ringbuf_t *ringbuf, uint8_t *out, size_t len) {
    const struct ringbuf *rb = (const struct ringbuf *)ringbuf;
    if (!rb || !out || len == 0) return 0;
    if (len > rb->stored) len = rb->stored;
    for (size_t i = 0; i < len; i++) {
        out[i] = rb->buf[rb->tail];
        /* tail unchanged */
        size_t p = rb->tail + 1;
        if (p >= rb->capacity) p -= rb->capacity;
    }
    return len;
}

size_t rb_size(const ringbuf_t *ringbuf) {
    const struct ringbuf *rb = (const struct ringbuf *)ringbuf;
    return rb ? rb->stored : 0;
}

size_t rb_capacity(const ringbuf_t *ringbuf) {
    const struct ringbuf *rb = (const struct ringbuf *)ringbuf;
    return rb ? rb->capacity : 0;
}

void rb_clear(ringbuf_t *ringbuf) {
    if (!ringbuf) return;
    struct ringbuf *rb = (struct ringbuf *)ringbuf;
    rb->stored = 0;
    rb->head   = 0;
    rb->tail   = 0;
}

